        public static bool TryParseUnit(string text, out UnitConverterRotationalStiffnessUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterRotationalStiffnessUnit)id : default(UnitConverterRotationalStiffnessUnit); return success;
        }

        public static UnitConverterRotationalStiffnessUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterRotationalStiffnessUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous RotationalStiffness unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterRotationalStiffnessValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterRotationalStiffnessValue(value, (UnitConverterRotationalStiffnessUnit)id) : default(UnitConverterRotationalStiffnessValue); return success;
        }

        public static UnitConverterRotationalStiffnessValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterRotationalStiffnessValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous RotationalStiffness unit.");
            return quantity;
        }

